package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.dto.ResolveReportRequest;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.server.ResponseStatusException;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class SanctionsExtraTest extends SocialServiceTest {
 @Autowired SanctionService sanctions;@Autowired AdminConsoleService admin;@Autowired com.dating.backend.config.JwtUtil jwt;
 UserReport report(){var r=UserReport.builder().reporterUserId(a.getId()).reportedUserId(b.getId()).reasonCode("OTHER").detail("test").build();em.persist(r);return r;}
 ResolveReportRequest decision(String action,Integer days){var r=new ResolveReportRequest();r.setAction(action);r.setDays(days);r.setPublicReason("서비스 이용규칙 위반");r.setAdminNote("internal confidential");return r;}
 @Test void warningCountIsIdempotentAndVisibleInSortedMembers(){var r=report();safety.resolveReport(r.getId(),decision("WARNING",null));safety.resolveReport(r.getId(),decision("WARNING",null));assertEquals(1,b.getWarningCount());assertEquals(b.getId(),admin.members("","ALL","ALL",0,"WARNINGS").items().get(0).id());assertEquals("WARNING",r.getResolutionAction());assertFalse(inbox.list(a.getEmail(),0).get(0).getBody().contains("confidential"));}
 @Test void temporarySuspensionRevokesSessionAndRestoresOnlyOnExpiry(){String token=jwt.createToken(b.getEmail());safety.resolveReport(report().getId(),decision("TEMPORARY",7));assertEquals("SUSPENDED",b.getStatus());assertFalse(jwt.validateToken(token));assertFalse(social.available(a.getId(),b.getId()));sanctions.expire(b.getId());assertEquals("SUSPENDED",b.getStatus());b.setSuspendedUntil(Instant.now().minusSeconds(1));sanctions.expire(b.getId());assertEquals("ACTIVE",b.getStatus());assertNull(b.getSanctionType());assertFalse(jwt.validateToken(token));}
 @Test void permanentSuspensionNeverExpiresAndInvalidDaysChangeNothing(){var r=report();assertThrows(ResponseStatusException.class,()->safety.resolveReport(r.getId(),decision("TEMPORARY",0)));assertEquals("ACTIVE",b.getStatus());safety.resolveReport(r.getId(),decision("PERMANENT",null));sanctions.expire(b.getId());assertEquals("SUSPENDED",b.getStatus());assertNull(b.getSuspendedUntil());assertEquals("PERMANENT",b.getSanctionType());}
 @Test void blockCountsRetainUnblocksWithoutCountingRetries(){social.direct(a.getEmail(),request());social.block(a.getEmail(),b.getId());social.block(a.getEmail(),b.getId());assertEquals(1,b.getTotalBlockCount());social.unblock(a.getEmail(),b.getId());assertEquals(1,b.getTotalBlockCount());social.block(a.getEmail(),b.getId());assertEquals(2,b.getTotalBlockCount());var m=admin.members("","ALL","ALL",0,"BLOCKS").items().get(0);assertEquals(b.getId(),m.id());assertEquals(2,m.totalBlockCount());assertEquals(1,m.activeBlockCount());}
 @Test void extraCardChargesOnlyOnceAndIsNotInEveningDeck(){for(int i=0;i<9;i++)person("extra"+i,"FEMALE");var q=daily.extraQuote(a.getEmail());assertEquals(10,q.cost());var r=new DailyMatchService.ExtraPurchase(day,10,java.util.UUID.randomUUID().toString());var extra=daily.buyExtra(a.getEmail(),r);assertEquals(6,extra.slot());assertEquals("OPEN",extra.state());assertEquals(extra,daily.buyExtra(a.getEmail(),r));assertEquals(90,em.find(CreditWallet.class,a.getId()).getBalance());assertEquals(1,em.createQuery("select count(e) from CreditEntry e where e.referenceKey like 'EXTRA:%'",Long.class).getSingleResult());time("2026-10-21T20:00:00");var deck=daily.today(a.getEmail());for(var card:deck.cards())if(card.slot()<6&&card.state().equals("HIDDEN")){var open=daily.reveal(a.getEmail(),day,card.slot());assertNotEquals(extra.profile().userId(),open.profile().userId());}time("2026-10-22T08:00:00");assertEquals(0,daily.extraQuote(a.getEmail()).purchasedCount());assertThrows(ResponseStatusException.class,()->daily.buyExtra(a.getEmail(),r));}
 @Test void noCandidateOrInsufficientBalanceDoesNotCharge(){assertThrows(ResponseStatusException.class,()->daily.buyExtra(a.getEmail(),new DailyMatchService.ExtraPurchase(day,10,java.util.UUID.randomUUID().toString())));assertEquals(100,em.find(CreditWallet.class,a.getId()).getBalance());assertEquals(0,daily.extraQuote(a.getEmail()).purchasedCount());person("extra","FEMALE");em.find(CreditWallet.class,a.getId()).setBalance(9);assertThrows(ResponseStatusException.class,()->daily.buyExtra(a.getEmail(),new DailyMatchService.ExtraPurchase(day,10,java.util.UUID.randomUUID().toString())));assertEquals(9,em.find(CreditWallet.class,a.getId()).getBalance());}
 @Test void multipleDistinctPurchasesHaveNoDailyLimitAndNoDuplicates(){for(int i=0;i<10;i++)person("unlimited"+i,"FEMALE");var one=new DailyMatchService.ExtraPurchase(day,10,java.util.UUID.randomUUID().toString());var two=new DailyMatchService.ExtraPurchase(day,10,java.util.UUID.randomUUID().toString());var first=daily.buyExtra(a.getEmail(),one);var second=daily.buyExtra(a.getEmail(),two);assertEquals(6,first.slot());assertEquals(7,second.slot());assertNotEquals(first.profile().userId(),second.profile().userId());assertEquals(second,daily.buyExtra(a.getEmail(),two));assertEquals(80,em.find(CreditWallet.class,a.getId()).getBalance());assertEquals(2,daily.extraQuote(a.getEmail()).purchasedCount());assertEquals("OPEN",daily.reveal(a.getEmail(),day,7).state());}
}
